{"tool": "sql", "args": {"query": "SELECT Ref_ID, Ref_DOI_number, Ref_lead_author, Ref_publication_date, Ref_journal, Cell_stack_sequence, ETL_stack_sequence, ETL_thickness, HTL_stack_sequence, HTL_thickness_list, Backcontact_stack_sequence, Backcontact_thickness_list, Substrate_stack_sequence, Perovskite_composition_short_form, Perovskite_composition_long_form, Perovskite_composition_a_ions, Perovskite_composition_b_ions, Perovskite_composition_c_ions, Perovskite_thickness, Perovskite_band_gap, JV_default_PCE, JV_default_Voc, JV_default_Jsc, JV_default_FF, ROUND(CAST(JV_default_FF AS REAL)*100,1) AS FF_pct, JV_default_PCE_scan_direction, JV_certified_values, JV_light_intensity, Cell_area_total, Cell_area_measured, Cell_number_of_cells_per_substrate, Stabilised_performance_PCE FROM devices WHERE Cell_architecture='nip' AND ETL_stack_sequence LIKE '%SnO2%' AND JV_default_PCE IS NOT NULL AND CAST(JV_default_PCE AS REAL) > 0 ORDER BY CAST(JV_default_PCE AS REAL) DESC LIMIT 10"}}
{"tool": "sql", "args": {"query": "SELECT CASE WHEN instr(ETL_stack_sequence,' | ')=0 THEN 'CAT1_single_SnO2_entry' WHEN ETL_stack_sequence LIKE 'SnO2%|%SnO2' OR ETL_stack_sequence LIKE '%SnO2%|%SnO2' THEN 'CAT2_bilayer_or_graded_SnO2' ELSE 'CAT3_SnO2_with_other_material' END AS cat, COUNT(*) AS n_devices, COUNT(DISTINCT Ref_DOI_number) AS n_papers, COUNT(JV_default_PCE) AS n_PCE, SUM(CASE WHEN JV_default_PCE IS NOT NULL AND JV_default_Voc IS NOT NULL AND JV_default_Jsc IS NOT NULL AND JV_default_FF IS NOT NULL THEN 1 ELSE 0 END) AS n_complete4, MAX(CAST(JV_default_PCE AS REAL)) AS max_PCE, ROUND(AVG(CAST(JV_default_PCE AS REAL)),3) AS mean_PCE FROM devices WHERE Cell_architecture='nip' AND ETL_stack_sequence LIKE '%SnO2%' GROUP BY 1 ORDER BY n_devices DESC"}}
